#include <bitset>
#include <iostream>
#include <stdexcept>

int main() {
    // Assuming unsigned long is 32 bits for demonstration
    std::bitset<33> large_bits;
    large_bits.set(32); // Value 2^32

    try {
        unsigned long val = large_bits.to_ulong();
        std::cout << "Value: " << val << std::endl;
    } catch (const std::overflow_error& e) {
        // Expected behavior if unsigned long < 33 bits
        std::cerr << "Error: " << e.what() << std::endl;
    }
}
